"""Publication swaps preserve old generated bytes and reject invalid input."""
import importlib.util
import json
import tempfile
import unittest
from pathlib import Path

SPEC=importlib.util.spec_from_file_location('study_manuals',Path(__file__).resolve().parents[2]/'tooling/manuals.py')
manuals=importlib.util.module_from_spec(SPEC);SPEC.loader.exec_module(manuals)


class ManualDeployTests(unittest.TestCase):
    def test_replace_keeps_previous_publication_and_only_copies_listed_resources(self):
        with tempfile.TemporaryDirectory() as temporary:
            root=Path(temporary);source=root/'source';(source/'manual').mkdir(parents=True)
            (source/'manual/manifest.json').write_text(json.dumps({'files':{'manual/page.md':{}}}))
            (source/'manual/page.md').write_text('new')
            (source/'private.txt').write_text('must not publish')
            target=root/'manual-publications/study';(target/'manual').mkdir(parents=True)
            (target/'manual/page.md').write_text('old')
            checked=[]
            backup=manuals.deploy(source,target,checker=lambda p,**_:checked.append(p))
            self.assertEqual((target/'manual/page.md').read_text(),'new')
            self.assertEqual((Path(backup)/'manual/page.md').read_text(),'old')
            self.assertFalse((target/'private.txt').exists());self.assertEqual(len(checked),3)

    def test_invalid_new_publication_does_not_move_existing_target(self):
        with tempfile.TemporaryDirectory() as temporary:
            root=Path(temporary);source=root/'source';source.mkdir();target=root/'manual-publications/study';target.mkdir(parents=True);(target/'keep').write_text('old')
            def reject(*_,**__):raise ValueError('invalid publication')
            with self.assertRaises(ValueError):manuals.deploy(source,target,checker=reject)
            self.assertEqual((target/'keep').read_text(),'old')


if __name__=='__main__':unittest.main()
